    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH')
      expect(req.url).toContain('/sobjects/Account/Website/example.com')
      expect(req.headers.get('authorization')).toBe('Bearer test-access-token')
      expect(req.json).toEqual({
        Name: 'Acme Corporation Deal',
        Website: 'example.com',
        Deal_ID__c: '98765'
      })
      return jsonResponse({ id: '001ABC123', success: true, created: true })
    })

    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })
    expect(result.salesforceAccountId).toBe('001ABC123')
    expect(result.created).toBe(true)
    expect(result.success).toBe(true)
