      ...SOURCE_EXAMPLE,
      object: { ...SOURCE_EXAMPLE.object, properties: { dealid: '123', website: 'test.com' } }
    }
    await expect(handle(badPayload as unknown as HubSpotDealWebhookPayload, baseConfig))
      .rejects.toThrow('Missing or invalid required field: object.properties.dealname')
  })

  it('throws descriptive error when website is missing', async () => {
    const badPayload = {
      ...SOURCE_EXAMPLE,
      object: { ...SOURCE_EXAMPLE.object, properties: { dealid: '123', dealname: 'Test' } }
    }
    await expect(handle(badPayload as unknown as HubSpotDealWebhookPayload, baseConfig))
