  })

  it('throws descriptive error when website is empty string', async () => {
    const badPayload = {
      ...SOURCE_EXAMPLE,
      object: { ...SOURCE_EXAMPLE.object, properties: { ...SOURCE_EXAMPLE.object.properties, website: '   ' } }
    }
    await expect(handle(badPayload as unknown as HubSpotDealWebhookPayload, baseConfig))
