  })

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Salesforce upsert failed: 401 Unauthorized for PATCH')
    expect(calls.length).toBe(1)
  })

  it('throws error when Salesforce returns success=false', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ id: '', success: false, errors: [{ message: 'Duplicate Website' }] }, 200))
    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Salesforce upsert returned success=false: {"message":"Duplicate Website"}')
    expect(calls.length).toBe(1)
  })

